"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["9071"],{53304(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>c,frontMatter:()=>s,contentTitle:()=>h,toc:()=>d,assets:()=>r});var o=JSON.parse('{"id":"tangfen/toflxdcsf2","title":"","description":"[Falanxi Dacai Shifu] came on today and immediately posted slandering me for saying the diagonal method is omnipotent. But his post shows he doesn\'t understand what the diagonal method is at all. He treats the diagonal method as a logical method like proof by contradiction, which is wrong. The diagonal method is merely a construction method. The diagonal method alone proves nothing -- it must be combined with logical methods to be useful. This is very basic mathematical common knowledge. This is precisely what I explicitly pointed out in my reply to that \\"Simen Zhu\\" character yesterday. Specifically for Miss Chan\'s example, the diagonal method is without problems in both its constructive aspect and its combination with proof by contradiction.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/toflxdcsf2.md","sourceDirName":"tangfen","slug":"/tangfen/toflxdcsf2","permalink":"/en/tangfen/toflxdcsf2","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"toflxdcsf2","title":"","hide_table_of_contents":true,"sidebar_label":"[French Chef], humans don\'t need to prove that their thoughts are human thoughts"},"sidebar":"tangfenSidebar","previous":{"title":"[French Chef], how did you make the same error again in the proof about all finite natural numbers?","permalink":"/en/tangfen/toflxdcsf1"},"next":{"title":"[French Chef], let me tell you once more what the diagonal method is!","permalink":"/en/tangfen/toflxdcsf3"}}'),a=n(74848),i=n(28453);let s={id:"toflxdcsf2",title:"",hide_table_of_contents:!0,sidebar_label:"[French Chef], humans don't need to prove that their thoughts are human thoughts"},h="[Falanxi Dacai Shifu], Humans Don't Need to Prove Their Thoughts Are Human Thoughts",r={},d=[];function l(e){let t={h1:"h1",header:"header",p:"p",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"falanxi-dacai-shifu-humans-dont-need-to-prove-their-thoughts-are-human-thoughts",children:"[Falanxi Dacai Shifu], Humans Don't Need to Prove Their Thoughts Are Human Thoughts"})}),"\n",(0,a.jsx)(t.p,{children:"[Falanxi Dacai Shifu] came on today and immediately posted slandering me for saying the diagonal method is omnipotent. But his post shows he doesn't understand what the diagonal method is at all. He treats the diagonal method as a logical method like proof by contradiction, which is wrong. The diagonal method is merely a construction method. The diagonal method alone proves nothing -- it must be combined with logical methods to be useful. This is very basic mathematical common knowledge. This is precisely what I explicitly pointed out in my reply to that \"Simen Zhu\" character yesterday. Specifically for Miss Chan's example, the diagonal method is without problems in both its constructive aspect and its combination with proof by contradiction."}),"\n",(0,a.jsx)(t.p,{children:"[Falanxi Dacai Shifu] has never understood the meaning of the definition in Miss Chan's proof, and has made the absurd demand that Miss Chan prove her definition is a human thought. Excuse me -- as long as Miss Chan is a human, Miss Chan's thoughts are naturally human thoughts, whether those thoughts are definitions or anything else. This reveals that this chef fundamentally hasn't distinguished between human thoughts and thoughts recordable by computers. Thoughts recordable by computers are connected to the Boolean algebra foundation of computers, which determines that computer-recordable thoughts must come character by character."}),"\n",(0,a.jsx)(t.p,{children:"In Miss Chan's proof, the diagonal construction is only one indispensable step, not the whole thing. It also utilizes the basic mode of computer recording. This mode determines that computer records in the real universe can only be finite. This too is an indispensable step in Miss Chan's proof -- without it, Miss Chan's proof wouldn't hold. Anyone with some mathematical and physics background can see this clearly!"}),"\n",(0,a.jsx)(t.p,{children:"Let me also add a supplementary point: human thought is not the same as propositions. Propositions can be right or wrong; thoughts don't necessarily have right or wrong. This is also one of the most important characteristics of human thought. Of course, this is unrelated to Miss Chan's proof, so I won't elaborate. Also, let that chef continue to study Miss Chan's proof carefully, and also understand this: humans don't need to prove their thoughts are human thoughts! Anything that can be thought of is a human thought. Whether it can be recorded is another matter entirely -- this is the fundamental difference between the human brain and the computer!"})]})}function c(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},28453(e,t,n){n.d(t,{R:()=>s,x:()=>h});var o=n(96540);let a={},i=o.createContext(a);function s(e){let t=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function h(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),o.createElement(i.Provider,{value:t},e.children)}}}]);